// Normaliza os dois tipos de update do Telegram num formato só.
// Retornar [] interrompe o fluxo — é assim que foto, sticker e entrada no
// grupo são descartados sem chamar o app.
const u = $input.first().json;

if (u.callback_query) {
  const cb = u.callback_query;
  return [{
    json: {
      rota: 'desfazer',
      chat_id: cb.message.chat.id,
      body: { token: String(cb.data || '').replace(/^desfazer:/, '') },
    },
  }];
}

const m = u.message || u.edited_message;
if (!m || !m.text) return [];

return [{
  json: {
    rota: 'mensagem',
    chat_id: m.chat.id,
    body: {
      chat_id: m.chat.id,
      message_id: m.message_id,
      user_id: m.from.id,
      nome: [m.from.first_name, m.from.last_name].filter(Boolean).join(' '),
      texto: m.text,
    },
  },
}];

// O app decide se vale responder. Silêncio é uma resposta válida:
// conversa entre o casal que não envolve o consultor não gera mensagem.
const r = $input.first().json;
if (r.responder === false) return [];
if (!r.texto) return [];
return [{ json: r }];
